"""Product detail content and contact readiness; no private profile data belongs here."""
from pathlib import Path
from html import escape
import json,re
ROOT=Path(__file__).resolve().parent.parent
DETAILS=[
 dict(page='booking-system.html',anchor='booking',name='AI-powered booking system',title='Make your own channels work harder.',lead='A planned direct booking engine for hotel and rental websites, with tools for availability, pricing suggestions and guest messaging.',who='Independent hotels, resorts and vacation rental operators looking to build their direct booking channel.',benefit='Bring booking information and guest communication closer to the property, with fewer separate tasks to coordinate.',features=[('Direct booking engine','Let guests make a booking through a hotel or rental website.'),('AI-assisted pricing suggestions','Give the property pricing suggestions to consider as part of its own decisions.'),('Availability management','Help operators keep track of which rooms or units can be booked.'),('Guest messaging','Support communication around a guest’s booking.')],workflow=[('Before the booking','A guest visits the property’s website to explore available accommodation.'),('At the booking','The planned engine supports a direct reservation and communication with the property.'),('At payment','A licensed third-party payment provider processes the payment and settles funds directly to the property.')],question='Will Dream Hospitality hold guest payments?',answer='No. The planned booking software does not collect or hold guest funds. Payments are processed by licensed third-party providers and settled directly to the hotel or operator.'),
 dict(page='contactless-check-in.html',anchor='check-in',name='Contactless check-in',title='A little less waiting. A better welcome.',lead='Planned mobile registration and self-service arrival tools for hotels, resorts and rental operators.',who='Properties looking to reduce manual arrival steps, including vacation rentals and serviced apartments.',benefit='Let guests prepare for arrival while helping the property organise the information it needs for check-in.',features=[('Pre-arrival registration','Allow guests to complete registration on a mobile device before arriving.'),('ID capture','Support capturing the identification information needed for registration.'),('Digital key integration','Planned integration with digital key technology, with supported systems to be confirmed.'),('Self check-in and check-out','Help guests complete arrival and departure steps through self-service tools.')],workflow=[('Before arrival','A guest completes the planned mobile registration process.'),('On arrival','The property uses the supplied registration details to support check-in.'),('At departure','Self check-out is planned to make the final step of the stay easier.')],question='Will it work with our existing door locks?',answer='Digital key integration is planned, but supported hardware, vendors and compatibility have not been confirmed. Those details need to be checked before making any purchasing decision.'),
 dict(page='guest-experience.html',anchor='guest-app',name='Guest experience app',title='Keep the guest connected to the stay.',lead='A planned property-branded app for guest requests, useful information, on-site services and feedback.',who='Hotels, resorts and accommodation operators looking for a clearer way to communicate with guests during their stay.',benefit='Bring everyday guest interactions into a property-branded experience, so guests have a clear place to find information and request help.',features=[('Property branding','An app experience planned to carry the property’s own brand.'),('Guest requests','Give guests a way to make requests during their stay.'),('Information and services','Make property information and on-site services easier to find.'),('Guest feedback','Provide a channel for guests to share feedback about their stay.')],workflow=[('Get familiar','A guest finds useful information about the property.'),('During the stay','The guest uses the planned app to request help or explore on-site services.'),('Share feedback','The guest can provide feedback for the property to review.')],question='Is this a finished app we can download?',answer='No. The guest experience app is in development. App availability, supported devices and launch details will be confirmed as development progresses.'),
 dict(page='property-management.html',anchor='pms',name='Cloud property management system',title='A clearer view of the everyday.',lead='A planned cloud PMS covering reservations, front desk, housekeeping and reporting for hospitality operators.',who='Independent and boutique properties, vacation rental operators, and small and mid-sized hotel groups.',benefit='Bring the core operational picture into one cloud system, helping teams coordinate the work behind a stay.',features=[('Reservations','Manage the property’s reservation information.'),('Front desk','Support the daily work of welcoming and looking after guests.'),('Housekeeping','Help teams organise housekeeping activity.'),('Reporting','Provide reporting to support the property’s operational decisions.')],workflow=[('Plan the day','Review reservations and the work ahead for the property.'),('Coordinate the team','Use the planned front desk and housekeeping tools to organise daily tasks.'),('Review operations','Use reporting to understand activity across the property.')],question='Which systems and channels will it integrate with?',answer='The confirmed product scope covers reservations, front desk, housekeeping and reporting. Specific integrations, supported channels and migration arrangements have not yet been announced.')
]

def brief_form():
 return '''<section class="section section-alt" id="property-brief"><div class="wrap enquiry-layout"><div><span class="label">Plan your next step</span><h2>What does your property need?</h2><p>Build a short brief to help organise a future conversation about your technology.</p><p class="note">This tool works only in your browser. It does not send anything to Dream Hospitality or save your answers. Please do not include personal or guest information.</p></div><div><form id="brief-form">
 <div class="form-grid"><div><label for="property-type">Property type</label><select id="property-type" name="propertyType" required><option value="">Choose a type</option><option>Independent or boutique hotel</option><option>Resort</option><option>Vacation rental</option><option>Serviced apartments</option><option>Hotel group</option></select></div><div><label for="property-size">Rooms or units</label><select id="property-size" name="propertySize" required><option value="">Choose a range</option><option>1–10</option><option>11–30</option><option>31–75</option><option>76–150</option><option>151+</option><option>Still planning</option></select></div></div>
 <fieldset class="needs" aria-describedby="needs-error"><legend>What would you like to improve?</legend><span class="field-help">Choose one or more.</span><label><input type="checkbox" name="needs" value="Direct bookings and availability">Direct bookings and availability</label><label><input type="checkbox" name="needs" value="Check-in and arrival">Check-in and arrival</label><label><input type="checkbox" name="needs" value="Guest communication and feedback">Guest communication and feedback</label><label><input type="checkbox" name="needs" value="Reservations, front desk and housekeeping">Reservations, front desk and housekeeping</label><label><input type="checkbox" name="needs" value="System selection or IT support">System selection or IT support</label><p class="field-error" id="needs-error" role="alert" hidden>Please choose at least one area to improve.</p></fieldset>
 <div class="form-grid"><div><label for="property-stage">Current stage</label><select id="property-stage" name="stage" required><option value="">Choose a stage</option><option>Planning a new property</option><option>Running an existing property</option><option>Expanding a group or portfolio</option></select></div><div><label for="property-timing">Preferred timing</label><select id="property-timing" name="timing" required><option value="">Choose a timeframe</option><option>Just exploring</option><option>Within 3 months</option><option>Within 6 months</option><option>Later / not decided</option></select></div></div><p class="note">Software is in development, with first modules planned for 2027. Selecting a timeframe does not reserve a product or confirm availability.</p><button type="submit" class="btn btn-dark">Prepare my brief</button><noscript><p>This browser tool needs JavaScript. You can instead note your property type, size and technology needs for a future enquiry.</p></noscript></form>
 <section id="brief-result" class="brief-result" aria-labelledby="brief-title" hidden><h3 id="brief-title" tabindex="-1">Your property brief</h3><pre id="brief-text"></pre><p>Prepared on this device. Nothing has been sent.</p><div class="cta-row"><button type="button" class="btn btn-dark" id="copy-brief">Copy brief</button><a class="btn btn-ghost" id="download-brief" download="dream-hospitality-property-brief.txt">Download brief (.txt)</a><a class="text-link" id="view-brief" target="_blank" rel="noopener">Open text version</a></div><p id="brief-status" role="status" aria-live="polite"></p></section></div></div></section>'''

def enquiry_form(email):
 return f'''<section class="section" id="enquiry"><div class="wrap enquiry-layout"><div><span class="label">Enquiries</span><h2>Tell us about your property.</h2><p>This form prepares an email to {escape(email)}. You will review and send it in your email app; the website does not send it automatically.</p></div><form id="enquiry-form" data-recipient="{escape(email,quote=True)}"><div class="form-grid"><div><label for="enquiry-name">Your name</label><input id="enquiry-name" name="name" autocomplete="name" maxlength="120" required></div><div><label for="enquiry-email">Email</label><input id="enquiry-email" name="email" type="email" autocomplete="email" maxlength="254" required></div><div><label for="enquiry-property">Property or company</label><input id="enquiry-property" name="property" autocomplete="organization" maxlength="180" required></div><div><label for="enquiry-phone">Phone (optional)</label><input id="enquiry-phone" name="phone" type="tel" autocomplete="tel" maxlength="40"></div></div><label for="enquiry-message">How can we help?</label><textarea id="enquiry-message" name="message" rows="6" maxlength="1500" required></textarea><p class="field-help">Please do not include guest records, identification documents or payment details.</p><label class="consent"><input type="checkbox" required>I have read the <a href="privacy-notice.html">Privacy Notice / Notis Privasi</a> and agree to my details being used to respond to this enquiry.</label><button type="submit" class="btn btn-dark">Prepare enquiry email</button><div id="enquiry-result" hidden><p>Your enquiry is ready to review. It has not been sent.</p><a id="enquiry-email-link" class="btn btn-dark">Open email app to review</a><p class="note">If an email app does not open, email {escape(email)} directly.</p></div></form></div></section>'''

def apply(pages,hero,cta):
 cfg=json.loads((ROOT/'_build/site-config.json').read_text())
 email=cfg.get('contact_email');phone=cfg.get('contact_phone')
 if email and not re.fullmatch(r'[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+',email):
  raise ValueError('Invalid contact email')
 ready=bool(email and cfg.get('privacy_approved') and cfg.get('privacy_contact'))
 for d in DETAILS:
  feats=''.join(f'<li><strong>{escape(a)}</strong>{escape(b)}</li>' for a,b in d['features'])
  steps=''.join(f'<li><h3>{escape(a)}</h3><p>{escape(b)}</p></li>' for a,b in d['workflow'])
  others=''.join(f'<a href="{x["page"]}">{escape(x["name"])}</a>' for x in DETAILS if x!=d)
  pages[d['page']]=dict(title=d['name']+' | Dream Hospitality',description=d['lead'],nav_parent='products.html',body=hero('Products · in development',d['title'],d['lead'])+f'''<section class="section"><div class="wrap"><a class="text-link" href="products.html">All products</a><div class="detail-summary"><div><span class="label">{escape(d['name'])}</span><h2>Designed around the property.</h2><p>{escape(d['benefit'])}</p></div><aside class="readiness"><span class="tag">In development</span><h3>Who it is for</h3><p>{escape(d['who'])}</p><p class="note">First modules in the suite are planned for 2027. A launch date for this module has not been confirmed.</p></aside></div></div></section><section class="section section-alt"><div class="wrap split"><div><span class="label">Planned capabilities</span><h2>What we are building.</h2><p>These capabilities describe the product plan and may change before launch.</p></div><ul class="checks">{feats}</ul></div></section><section class="section"><div class="wrap"><div class="section-head"><span class="label">An example journey</span><h2>How it could fit your day.</h2><p>An illustration of the planned experience, rather than a currently available service.</p></div><ol class="steps journey-steps">{steps}</ol></div></section><section class="section section-alt"><div class="wrap faq"><span class="label">Before you plan</span><h2>A few useful answers.</h2><details><summary>{escape(d['question'])}</summary><p>{escape(d['answer'])}</p></details><details><summary>Is this product available now?</summary><p>No. This product is in development. First modules in the suite are planned for 2027; individual module dates and final capabilities will be confirmed later.</p></details><details><summary>What will it cost?</summary><p>The software is planned mainly as a subscription, with implementation, hotel group licensing and support options. Pricing and packages have not been announced.</p></details><details><summary>How can I prepare?</summary><p>Use our property brief tool to note your property type, size and the areas you would like to improve. It creates a brief on your device without sending it.</p><a href="contact.html#property-brief">Prepare a property brief</a></details><nav class="chip-nav related-products" aria-label="Other products">{others}</nav></div></section>''' + cta('Plan around your property.', 'Create a short brief covering your property and technology priorities.', 'Prepare a property brief'))
  link=f'<a class="text-link" href="{d["page"]}">Explore {escape(d["name"])}</a>'
  # Insert into the corresponding product's overview without changing its anchor.
  marker=f'<article class="product" id="{d["anchor"]}">';start=pages['products.html']['body'].index(marker);end=pages['products.html']['body'].index('</article>',start)
  part=pages['products.html']['body'][start:end];part=part.replace('</p>','</p>'+link,1);pages['products.html']['body']=pages['products.html']['body'][:start]+part+pages['products.html']['body'][end:]
  pages['index.html']['body']=pages['index.html']['body'].replace('products.html#'+d['anchor'],d['page'])
 body=pages['contact.html']['body']
 if email or phone:
  contact='<h2>Let’s talk about your property.</h2>'
  if email:contact+=f'<p><a href="mailto:{escape(email,quote=True)}">{escape(email)}</a></p>'
  if phone:contact+=f'<p><a href="tel:{re.sub(r"[^+0-9]","",phone)}">{escape(phone)}</a></p>'
  if not ready:contact+='<p>For now, please contact us directly. Online enquiry email preparation will be available once the privacy notice is approved.</p>'
  body=re.sub(r'<h2>Contact details are being finalised.</h2>\s*<p>.*?</p>',lambda m:contact,body,count=1,flags=re.S)
 body+=brief_form()
 if ready:body+=enquiry_form(email)
 pages['contact.html']['body']=body
 return ready
